import{dodge}from"./chartData.f71c7d5a.js";const SHORT_MONTH=new Intl.DateTimeFormat("en-US",{month:"short"});const AXIS_ROW=55;const LOG_ROW=30;function round(value){return+value.toFixed(10)}function niceStep(raw){const power=10**Math.floor(Math.log10(raw));const fraction=raw/power;return(fraction<=1.25?1:fraction<=2.5?2:fraction<=5.5?5:10)*power}function linearAxis(min,max,plotHeight){const count=Math.max(3,Math.round(plotHeight/AXIS_ROW));const step=niceStep((max-min)/count);const lo=Math.floor(min/step);const hi=Math.ceil(max/step);const ticks=[];for(let i=lo;i<=hi;i++)ticks.push(round(i*step));return{domain:[ticks[0],ticks.at(-1)],ticks}}function logTicks(min,max,multiples){const ticks=[];for(let power=Math.floor(Math.log10(min))-1;power<=Math.ceil(Math.log10(max));power++){for(const m of multiples)ticks.push(round(m*10**power))}const lo=ticks.findLast(t=>t<=min);const hi=ticks.find(t=>t>=max);return ticks.filter(t=>t>=lo&&t<=hi)}function logAxis(min,max,plotHeight){const budget=Math.max(3,Math.round(plotHeight/LOG_ROW));let ticks=logTicks(min,max,[1,2,5]);if(ticks.length>budget)ticks=logTicks(min,max,[1,3]);if(ticks.length>budget)ticks=logTicks(min,max,[1]);return{domain:[ticks[0],ticks.at(-1)],ticks}}function yAxis({min,max,plotHeight,log=false,head=0}){const pad=min===max?Math.abs(min)*.05||1:0;const lo=min-pad;const hi=max+pad;if(log){const room=head?hi*(hi/lo)**(head/plotHeight):hi;return logAxis(lo,room,plotHeight)}return linearAxis(lo,hi+head/plotHeight*(hi-lo),plotHeight)}const TICK_MONTHS=[1,3,6,12,24,60,120];const TICK_GAP=48;function monthIndex(date){return date.getFullYear()*12+date.getMonth()}function ticksEvery(months,start,end){const first=Math.ceil((start.getFullYear()*12+start.getMonth()+(start.getDate()>1?1:0))/months)*months;const ticks=[];for(let m=first;m<=monthIndex(end);m+=months)ticks.push(new Date(Math.floor(m/12),m%12,1));return ticks}function timeTicks({start,end,plotWidth}){const span=Math.max(1,monthIndex(end)-monthIndex(start));const perMonth=plotWidth/span;let chosen=TICK_MONTHS.find(m=>m*perMonth>=TICK_GAP)??TICK_MONTHS.at(-1);let ticks=ticksEvery(chosen,start,end);while(ticks.length<2&&chosen>1){chosen=TICK_MONTHS[TICK_MONTHS.indexOf(chosen)-1];ticks=ticksEvery(chosen,start,end)}const yearly=chosen>=12;const first=ticks[0];const format=date=>{if(yearly)return String(date.getFullYear());const name=SHORT_MONTH.format(date);return date.getMonth()===0||+date===+first?`${name}
${date.getFullYear()}`:name};return{ticks,format}}function rightRoom({width,left,labelRoom,stretch,floor=12}){if(!stretch)return labelRoom;const needed=width-left-(width-left-labelRoom)/(1-stretch);return Math.max(floor,Math.ceil(needed))}function lonePoints(data){const shown=(d,key)=>d?.key===key&&d.value!=null;return data.filter((d,i)=>d.value!=null&&!shown(data[i-1],d.key)&&!shown(data[i+1],d.key))}function columnLabels(items,{column,gap,top,bottom,threshold}){const sorted=[...items].sort((a,b)=>a.py-b.py);const py=dodge(sorted,{gap,top,bottom});return sorted.map((item,i)=>({...item,labelY:py[i],leader:Math.abs(py[i]-item.py)>=threshold||item.endX<column-1}))}function candidates(px,py,fit,lineHeight,gap){const height=fit.lines.length*lineHeight;const{width}=fit;const above={top:py-gap-height,bottom:py-gap,lineAnchor:"bottom",dy:-gap};const below={top:py+gap,bottom:py+gap+height,lineAnchor:"top",dy:gap};const beside={top:py-height/2,bottom:py+height/2,lineAnchor:"middle",dy:0};const horizontal=row=>[{...row,left:px,right:px+width,textAnchor:"start",dx:0},{...row,left:px-width,right:px,textAnchor:"end",dx:0},{...row,left:px-width/2,right:px+width/2,textAnchor:"middle",dx:0}];return[...horizontal(above),...horizontal(below),{...beside,left:px+gap,right:px+gap+width,textAnchor:"start",dx:gap},{...beside,left:px-gap-width,right:px-gap,textAnchor:"end",dx:-gap}]}function overlapArea(a,b){const x=Math.min(a.right,b.right)-Math.max(a.left,b.left);const y=Math.min(a.bottom,b.bottom)-Math.max(a.top,b.top);return x>0&&y>0?x*y:0}function insideLength([x1,y1,x2,y2],box){const dx=x2-x1;const dy=y2-y1;let t0=0;let t1=1;const edges=[[-dx,x1-box.left],[dx,box.right-x1],[-dy,y1-box.top],[dy,box.bottom-y1]];for(const[p,q]of edges){if(p===0){if(q<0)return 0;continue}const t=q/p;if(p<0)t0=Math.max(t0,t);else t1=Math.min(t1,t);if(t0>t1)return 0}return(t1-t0)*Math.hypot(dx,dy)}const COST={outside:2e3,onLabel:40,onBox:20,onLine:12,wrapped:30,rank:1};function cost(box,rank,extraLines,{bounds,segments,boxes},others){const outside=Math.max(0,bounds.left-box.left)+Math.max(0,box.right-bounds.right)+Math.max(0,bounds.top-box.top)+Math.max(0,box.bottom-bounds.bottom);let total=outside*COST.outside+rank*COST.rank+extraLines*COST.wrapped;for(const other of others)total+=overlapArea(box,other)*COST.onLabel;for(const other of boxes)total+=overlapArea(box,other)*COST.onBox;for(const segment of segments)total+=insideLength(segment,box)*COST.onLine;return total}function placeLabels(items,{bounds,segments=[],boxes=[],gap=9}){const scene={bounds,segments,boxes};const placed=[];const choose=(item,others)=>{let best=null;item.fits.forEach((fit,f)=>{candidates(item.px,item.py,fit,item.lineHeight,gap).forEach((spot,rank)=>{const score=cost(spot,rank,f,scene,others);if(!best||score<best.score){const{left,right,top,bottom,textAnchor,lineAnchor,dx,dy}=spot;best={score,lines:fit.lines,textAnchor,lineAnchor,dx,dy,box:{left,right,top,bottom}}}})});return best};items.forEach(item=>placed.push(choose(item,placed.map(p=>p.box))));items.forEach((item,i)=>{placed[i]=choose(item,placed.filter((_,j)=>j!==i).map(p=>p.box))});return placed.map(({score,...rest})=>rest)}function legendRows(items,{width,key=16,gap=14,lineHeight=17}){const rows=[];let x=0;let y=0;let rowLines=1;for(const item of items){const needed=key+item.width;if(x>0&&x+needed>width){x=0;y+=rowLines*lineHeight;rowLines=1}rows.push({key:item.key,lines:item.lines,x,y});x+=needed+gap;rowLines=Math.max(rowLines,item.lines.length)}return{rows,height:y+rowLines*lineHeight}}export{columnLabels,legendRows,lonePoints,placeLabels,rightRoom,timeTicks,yAxis};
